create table if not exists platform.runs (run_id uuid primary key,tenant_id uuid not null references platform.tenants(tenant_id),task_id uuid not null references platform.tasks(task_id),status text not null check(status in ('created','running','waiting_approval','succeeded','failed','cancelled')),turn_count integer not null default 0 check(turn_count>=0),approval_id uuid,failure_code text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists platform.approvals (approval_id uuid primary key,tenant_id uuid not null references platform.tenants(tenant_id),run_id uuid not null references platform.runs(run_id),action text not null,resource text not null,reason text not null,requested_by text not null,status text not null check(status in ('pending','approved','rejected','expired')),created_at timestamptz not null default now(),decided_at timestamptz);
create table if not exists platform.run_budgets (budget_id uuid primary key,tenant_id uuid not null references platform.tenants(tenant_id),run_id uuid not null unique references platform.runs(run_id),max_turns integer not null check(max_turns>0),max_seconds double precision not null check(max_seconds>0),max_tool_calls integer not null check(max_tool_calls>=0),consumed_turns integer not null default 0 check(consumed_turns>=0),consumed_tool_calls integer not null default 0 check(consumed_tool_calls>=0),elapsed_seconds double precision not null default 0 check(elapsed_seconds>=0));
alter table platform.runs enable row level security; alter table platform.runs force row level security;
alter table platform.approvals enable row level security; alter table platform.approvals force row level security;
alter table platform.run_budgets enable row level security; alter table platform.run_budgets force row level security;
create policy runs_tenant_isolation on platform.runs using(tenant_id=platform.current_tenant_id()) with check(tenant_id=platform.current_tenant_id());
create policy approvals_tenant_isolation on platform.approvals using(tenant_id=platform.current_tenant_id()) with check(tenant_id=platform.current_tenant_id());
create policy budgets_tenant_isolation on platform.run_budgets using(tenant_id=platform.current_tenant_id()) with check(tenant_id=platform.current_tenant_id());
create index if not exists idx_runs_tenant_status on platform.runs(tenant_id,status);
create index if not exists idx_approvals_tenant_status on platform.approvals(tenant_id,status);
